const fs = require('fs');

const TYPESENSE_HOST = 'http://127.0.0.1:8108';
const API_KEY = '7Cr22g6RGYrHcWHh9h0V8UoNzFNirvXr';

async function init() {
  console.log('Initializing Typesense collection...');

  // 1. Delete collection if exists
  try {
    const deleteRes = await fetch(`${TYPESENSE_HOST}/collections/knowledge_base`, {
      method: 'DELETE',
      headers: {
        'X-TYPESENSE-API-KEY': API_KEY
      }
    });
    const deleteJson = await deleteRes.json();
    console.log('Deleted existing collection (if any):', deleteJson);
  } catch (err) {
    console.log('Error deleting collection:', err.message);
  }

  // 2. Create collection
  const schema = {
    name: 'knowledge_base',
    fields: [
      { name: 'title', type: 'string' },
      { name: 'body', type: 'string' },
      { name: 'embedding', type: 'float[]', num_dim: 8 }
    ]
  };

  const createRes = await fetch(`${TYPESENSE_HOST}/collections`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-TYPESENSE-API-KEY': API_KEY
    },
    body: JSON.stringify(schema)
  });

  if (!createRes.ok) {
    const errText = await createRes.text();
    throw new Error(`Failed to create collection: ${errText}`);
  }

  const createJson = await createRes.json();
  console.log('Created collection:', createJson);

  // 3. Read documents
  const docsData = JSON.parse(fs.readFileSync('/home/user/kbsearch/data/documents.json', 'utf8'));
  console.log(`Loaded ${docsData.length} documents from JSON.`);

  // 4. Import documents
  // Typesense import endpoint accepts newline-delimited JSON (NDJSON)
  const ndjson = docsData.map(doc => JSON.stringify(doc)).join('\n');

  const importRes = await fetch(`${TYPESENSE_HOST}/collections/knowledge_base/documents/import?action=upsert`, {
    method: 'POST',
    headers: {
      'Content-Type': 'text/plain',
      'X-TYPESENSE-API-KEY': API_KEY
    },
    body: ndjson
  });

  if (!importRes.ok) {
    const errText = await importRes.text();
    throw new Error(`Failed to import documents: ${errText}`);
  }

  const importText = await importRes.text();
  console.log('Import response:', importText);
  console.log('Initialization complete!');
}

init().catch(err => {
  console.error('Initialization failed:', err);
  process.exit(1);
});

