async function test() {
  const queryVectors = JSON.parse(fs.readFileSync('/home/user/kbsearch/data/query_vectors.json', 'utf8'));
  const queryText = "speed up slow website";
  const vector = queryVectors[queryText];

  console.log(`Query: "${queryText}"`);
  console.log('Vector:', vector);

  // 1. Keyword search
  {
    const res = await fetch(`${TYPESENSE_HOST}/collections/knowledge_base/documents/search?q=${encodeURIComponent(queryText)}&query_by=title,body`, {
      headers: { 'X-TYPESENSE-API-KEY': API_KEY }
    });
    const json = await res.json();
    console.log('\n--- Keyword Search ---');
    if (json.hits) {
      json.hits.forEach(hit => {
        console.log(`ID: ${hit.document.id}, Title: "${hit.document.title}", Score: ${hit.text_match_score || hit.hybrid_search_info?.text_match_score || hit.score}`);
      });
    } else {
      console.log(json);
    }
  }

  // 2. Semantic search
  {
    const vectorStr = `[${vector.join(',')}]`;
    const res = await fetch(`${TYPESENSE_HOST}/collections/knowledge_base/documents/search?q=*&vector_query=embedding:(${vectorStr}, k:10)`, {
      headers: { 'X-TYPESENSE-API-KEY': API_KEY }
    });
    const json = await res.json();
    console.log('\n--- Semantic Search (q=*, vector_query) ---');
    if (json.hits) {
      json.hits.forEach(hit => {
        console.log(`ID: ${hit.document.id}, Title: "${hit.document.title}", Score: ${hit.score || hit.vector_distance}`);
      });
    } else {
      console.log(json);
    }
  }

  // 3. Hybrid search
  {
    const vectorStr = `[${vector.join(',')}]`;
    const res = await fetch(`${TYPESENSE_HOST}/collections/knowledge_base/documents/search?q=${encodeURIComponent(queryText)}&query_by=title,body&vector_query=embedding:(${vectorStr}, k:10, alpha:0.5)`, {
      headers: { 'X-TYPESENSE-API-KEY': API_KEY }
    });
    const json = await res.json();
    console.log('\n--- Hybrid Search (alpha=0.5) ---');
    if (json.hits) {
      json.hits.forEach(hit => {
        console.log(`ID: ${hit.document.id}, Title: "${hit.document.title}", Score: ${hit.score}`);
      });
    } else {
      console.log(json);
    }
  }
}

